module Top;
    int q[$];
    byte signed d[];
    string names[$];
    int i;
    string s, t;
    initial begin
        q = {1, 2, 3};
        d = new[2];
        d[0] = -1;
        d[1] = 5;
        names = {"p", "q"};
        i = -7;
        t = "str";
        $display("%p|%p|%p|%p|%p|%0p", q, d, names, i, t, q);
        s = $sformatf("%p|%p|%p|%p|%p|%0p", q, d, names, i, t, q);
        $display("%s", s);
        q.delete();
        $display("[%p]", q);
    end
endmodule

module Top;
    int a[string];
    bit [7:0] m[int];
    initial begin
        a["x"] = 10;
        a["a"] = 20;
        m[-2] = 8'h41;
        m[7] = 8'h0;
        $display("%p|%p", a, m);
    end
endmodule

class Item; int id; endclass
module Top;
    Item item, items[$];
    initial begin
        items.push_back(null);
        items.push_back(null);
        $display("%p|%p|%p", items, item, "lit");
    end
endmodule

